--
-- Name: asset_requests; Type: TABLE; Schema: bayanat; Owner: -
--

CREATE TABLE bayanat.asset_requests (
    request_id integer NOT NULL,
    request_type_code character varying(30) NOT NULL,
    title text NOT NULL,
    description_text text,
    priority_code character varying(10) DEFAULT 'MEDIUM'::character varying NOT NULL,
    status_code character varying(20) DEFAULT 'OPEN'::character varying NOT NULL,
    raised_by_user_id character varying(255) NOT NULL,
    assigned_to_user_id character varying(255),
    resolution_notes text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT asset_requests_priority_code_check CHECK (((priority_code)::text = ANY ((ARRAY['HIGH'::character varying, 'MEDIUM'::character varying, 'LOW'::character varying])::text[]))),
    CONSTRAINT asset_requests_request_type_code_check CHECK (((request_type_code)::text = ANY ((ARRAY['FIX_DATA_ISSUE'::character varying, 'UPDATE_DEFINITION'::character varying, 'CERTIFY_ASSET'::character varying, 'GRANT_ACCESS'::character varying, 'REMOVE_ACCESS'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT asset_requests_status_code_check CHECK (((status_code)::text = ANY ((ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'RESOLVED'::character varying, 'CLOSED'::character varying])::text[])))
);


